    _firstCtrl.dispose();
    _lastCtrl.dispose();
    super.dispose();
  }

  String? _validateEmail(String? v) {
    final value = v?.trim() ?? '';
    if (value.isEmpty) return 'Email required';
    final re = RegExp(r'^[^@]+@[^@]+\.[^@]+$');
    if (!re.hasMatch(value)) return 'Enter a valid email';
    return null;
  }

  String? _validatePassword(String? v) {
    if (v == null || v.isEmpty) return 'Password required';
    if (v.length < 6) return 'Min 6 characters';
    return null;
  }

  String? _validateName(String? v, String label) {
    if (v == null || v.trim().isEmpty) return '$label required';
    if (v.trim().length < 2) return '$label too short';
    return null;
  }

  Future<void> _signup() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() => _loading = true);
    try {
      final email = _emailCtrl.text.trim();
      final pwd = _pwdCtrl.text;
      final firstName = _firstCtrl.text.trim();
      final lastName = _lastCtrl.text.trim();

      final cred = await _auth.signUpWithEmailAndPassword(email: email, password: pwd);
      final uid = cred.user!.uid;

      // Save first/last name to Firestore under users/<uid>
      await _repo.saveUserProfile(
        uid: uid,
        email: email,
        firstName: firstName,
        lastName: lastName,
      );

      // Optionally reflect name in Firebase Auth profile
      await _auth.updateProfile(displayName: '$firstName $lastName');

      if (!mounted) return;
      Navigator.pushNamed(context, ProfileDetailsPage.routeName);
    } on FirebaseAuthException catch (e) {
      if (!mounted) return;
