class OnboardingState extends ChangeNotifier {
  String? email;
  String? password;
  String? firstName;
  String? lastName;
  double? weight;
  double? height;
  String? bodyType;
  File? photoFile;

  void setEmail(String value) {
    email = value.trim();
    notifyListeners();
  }

  void setPassword(String value) {
    password = value;
    notifyListeners();
  }

  void setName(String first, String last) {
    firstName = first.trim();
    lastName = last.trim();
    notifyListeners();
  }

  void setMetrics({double? weightKg, double? heightCm, String? body}) {
    weight = weightKg;
    height = heightCm;
    bodyType = body;
    notifyListeners();
  }

  void setPhoto(File? file) {
    photoFile = file;
    notifyListeners();
  }

  void reset() {
    email = null;
    password = null;
    firstName = null;
    lastName = null;
    weight = null;
    height = null;
    bodyType = null;
    photoFile = null;
    notifyListeners();
  }
}


