            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen or " " in lw:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


