```python
# src/lookup/indexer.ts
import { XMLParser } from 'fast-xml-parser';

type IndexMap = Map<string, any[]>;
type FieldIndex = Record<string, IndexMap>;

export interface BuildOptions {
  primaryKey: string;
  indexFields: string[];
  recordPath: string;   // dot path to array in parsed XML
  normalizer?: (v: any) => string;
}

export interface InMemoryStore {
  records: any[];
  byId: Map<string, any>;
  indexes: FieldIndex; // field -> (value -> [records])
}

const defaultNormalizer = (v: any) =>
  typeof v === 'string'
    ? v.normalize('NFC').trim().toLowerCase()
    : String(v);

const getByPath = (obj: any, path: string) =>
  path.split('.').reduce((acc, k) => (acc ? acc[k] : undefined), obj);

export async function buildStoreFromXml(xmlText: string, opts: BuildOptions): Promise<InMemoryStore> {
  const normalizer = opts.normalizer ?? defaultNormalizer;
  const parser = new XMLParser({ ignoreAttributes: false, trimValues: true, allowBooleanAttributes: true });
  const parsed = parser.parse(xmlText);

  const arr = getByPath(parsed, opts.recordPath);
  if (!Array.isArray(arr)) {
    throw new Error(`XML_RECORD_PATH did not resolve to an array: ${opts.recordPath}`);
  }

  const records = arr;
  const byId = new Map<string, any>();
  const indexes: FieldIndex = {};

  const allIndexFields = Array.from(new Set([opts.primaryKey, ...opts.indexFields]));
  for (const field of allIndexFields) indexes[field] = new Map();

  for (const r of records) {
    const idRaw = r[opts.primaryKey];
    if (idRaw == null) continue;
    const id = normalizer(idRaw);
    byId.set(id, r);

    for (const field of allIndexFields) {
      const raw = r[field];
      if (raw == null) continue;
      const key = normalizer(raw);
      const map = indexes[field];
      const list = map.get(key);
      if (list) list.push(r);
      else map.set(key, [r]);
    }
  }

  return { records, byId, indexes };
}

export function lookup(store: InMemoryStore, field: string, value: string, normalizer = defaultNormalizer) {
  const f = store.indexes[field];
  if (!f) return [];
  return f.get(normalizer(value)) || [];
}
```

2) Minimal controller using the in-memory store with an atomic reload
```python
# src/lookup/lookup.controller.ts
import { Controller, Get, Post, Query, Res, Req, HttpException, HttpStatus } from '@nestjs/common';
import { readFile } from 'node:fs/promises';
import { buildStoreFromXml, lookup, InMemoryStore } from './indexer';

let STORE: InMemoryStore | null = null;
let RELOADING = false;

async function loadOrReload(): Promise<void> {
  const xmlPath = process.env.XML_PATH || '/app/data/records.xml';
  const recordPath = process.env.XML_RECORD_PATH || 'records.record';
  const primary = process.env.PRIMARY_KEY_FIELD || 'id';
  const fields = (process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim()).filter(Boolean);
  const xml = await readFile(xmlPath, 'utf-8');
  const next = await buildStoreFromXml(xml, { primaryKey: primary, indexFields: fields, recordPath });
  STORE = next; // atomic swap
}

@Controller('lookup')
export class LookupController {
  constructor() {
    // fire and forget at first request time if not eager-loaded in module init
    if (!STORE) loadOrReload().catch(err => console.error('Initial load failed:', err));
  }

  @Get()
  async get(@Query('field') field: string, @Query('value') value: string) {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    if (!field || value == null) throw new HttpException('field and value are required', HttpStatus.BAD_REQUEST);
    return lookup(STORE, field, value);
  }

  @Get('count')
  count() {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    return { count: STORE.records.length };
  }

  @Post('reload')
  async reload(@Req() req) {
    const token = req.headers['x-admin-token'];
    if (token !== (process.env.RELOAD_TOKEN || 'change-me')) {
      throw new HttpException('Forbidden', HttpStatus.FORBIDDEN);
    }
    if (RELOADING) return { status: 'already_reloading' };
    RELOADING = true;
    try {
      await loadOrReload();
      return { status: 'ok' };
    } finally {
      RELOADING = false;
    }
  }

  @Get('fields')
  fields() {
    if (!STORE) throw new HttpException('Service warming up', HttpStatus.SERVICE_UNAVAILABLE);
    return { fields: Object.keys(STORE.indexes) };
  }
}
```

