    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
