func pretty(w []float64) string {
	var b strings.Builder
	b.WriteString("[")
	for i, v := range w {
		if i > 0 {
			b.WriteString(" ")
		}
		b.WriteString(fmt.Sprintf("%.4f", v))
	}
	b.WriteString("]")
	return b.String()
}

