	tauLow := math.Inf(1)
	tauHigh := math.Inf(-1)
	for i := 0; i < n; i++ {
		low := w[i] - maxW[i]  // if tau <= low => y_i = maxW[i]
		high := w[i] - minW[i] // if tau >= high => y_i = minW[i]
		if low < tauLow {
			tauLow = low
		}
		if high > tauHigh {
			tauHigh = high
		}
	}

	// Bisection on tau
	for iter := 0; iter < 80; iter++ {
		tau := 0.5 * (tauLow + tauHigh)
		sum := 0.0
		for i := 0; i < n; i++ {
			v := w[i] - tau
			if v < minW[i] {
				v = minW[i]
			}
			if v > maxW[i] {
				v = maxW[i]
			}
			sum += v
		}
		if sum > 1.0 {
			// Need to reduce sum -> increase tau
			tauLow = tau
		} else {
			// Need to increase sum -> decrease tau
			tauHigh = tau
		}
	}

	tau := 0.5 * (tauLow + tauHigh)
	for i := 0; i < n; i++ {
		v := w[i] - tau
		if v < minW[i] {
			v = minW[i]
		}
		if v > maxW[i] {
			v = maxW[i]
		}
		w[i] = v
	}

	// Optional tiny correction for numerical drift
	sum := 0.0
	freeIdx := make([]int, 0, n)
	for i := 0; i < n; i++ {
		sum += w[i]
		if w[i] > minW[i]+1e-12 && w[i] < maxW[i]-1e-12 {
			freeIdx = append(freeIdx, i)
		}
	}
	diff := 1.0 - sum
