Below is a complete, self‑contained Flask app that you can deploy (Render, Railway, Fly.io, Heroku, etc.) and embed on your Square.com site. It includes:

- Ingredient extraction from pasted text or uploaded .txt/.pdf
- Wikipedia/Wikidata/Datamuse lookups (no keys required)
- Timeouts, retries (lightweight), and error handling
- An embeddable UI at /embed that you can iframe into Square

How to embed on Square:
1) Deploy this app to a public URL, e.g., https://your-spell-app.example.com
2) In Square Online > Website > Edit site > Add section > Embed code, paste:
   <iframe src="https://your-spell-app.example.com/embed" width="100%" height="920" style="border:0;max-width:100%"></iframe>
3) Publish.

Notes:
- This is for creative/entertainment purposes.
- PDF text extraction uses PyPDF2 (optional); .txt supported.
- Public endpoints only; no API keys.
- Default network timeout is 4 seconds per call.

```python
# app.py
import io
import re
import json
import html
import logging
import time
from typing import List, Dict, Optional, Tuple
from collections import OrderedDict

from flask import Flask, request, jsonify, Response, redirect, url_for, make_response
import requests

# Optional PDF support
try:
    import PyPDF2
    HAS_PDF = True
except Exception:
    HAS_PDF = False

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024  # 2MB limit

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("spell-app")

# --------- Ingredient Parsing ---------

UNITS = {
    "cup", "cups", "tsp", "teaspoon", "teaspoons", "tbsp", "tablespoon", "tablespoons",
    "g", "gram", "grams", "kg", "kilogram", "kilograms", "ml", "l", "liter", "liters",
    "oz", "ounce", "ounces", "lb", "pound", "pounds",
    "pinch", "dash", "slice", "slices", "clove", "cloves", "piece", "pieces",
    "can", "cans", "package", "packages", "pkg", "small", "medium", "large"
}
STOPWORDS = {
    "fresh", "dried", "ground", "minced", "chopped", "sliced", "grated", "crushed",
    "to", "taste", "and", "or", "optional", "about", "of"
}
SECTION_BREAKERS = {
    "instructions", "method", "directions", "steps", "preparation", "prep", "cook", "cooking", "baking", "notes"
}
USER_AGENT = {"User-Agent": "SpellWidget/1.0 (+https://example.com)"}
HTTP_TIMEOUT = 4.0

def normalize_ingredient_line(line: str) -> Optional[str]:
    # Remove parenthetical notes
    line = re.sub(r"\([^)]*\)", "", line)
    line = line.strip().lstrip("-•*").strip()
    # Remove leading quantities like "1 1/2", "2", "2-3", "200 g", etc.
    line = re.sub(r"^\s*(\d+([\/\.\-]\d+)?(\s+\d+\/\d+)?\s*)+", "", line)
    # Remove fraction like "½"
    line = re.sub(r"^[¼½¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞]+\s*", "", line)
    tokens = [t for t in re.split(r"[,\s]+", line) if t]
    if len(tokens) == 0:
        return None

    # Skip initial unit tokens
    i = 0
    while i < len(tokens) and tokens[i].lower() in UNITS:
        i += 1
    cleaned = tokens[i:] if i < len(tokens) else []

    if not cleaned:
        return None

    # Remove common stopwords
    cleaned = [t for t in cleaned if t.lower() not in STOPWORDS]

    if cleaned and cleaned[0].lower() == "of":
        cleaned = cleaned[1:]

    ing = " ".join(cleaned)
    ing = ing.strip(" ,.;:-").strip()

    pieces = ing.split()
    if len(pieces) > 5:
        ing = " ".join(pieces[-3:])  # keep the likely core, e.g., "brown sugar"

    ing = re.sub(r"\s+", " ", ing).strip().lower()

    if not ing or len(ing) < 2:
        return None

    # Exclude section headers and non-ingredient lines
    if any(h in ing for h in SECTION_BREAKERS):
        return None
    if ing.startswith(("serves", "yield", "time", "total time", "prep time", "cook time")):
        return None
    # Avoid lines that are likely headings
    if len(ing.split()) <= 1 and ing.isalpha() is False:
        return None

    # Trim trailing descriptors like "to taste"
    ing = re.sub(r"\b(to taste|as needed)\b", "", ing).strip()
    return ing if ing else None

def extract_ingredients_from_text(text: str, limit: int = 20) -> List[str]:
    lines = [l.strip() for l in text.splitlines()]
    # Try to find an "Ingredients" section
    ingredients_block: List[str] = []
    in_ing = False
    found_section = False

    for line in lines:
        low = line.strip().lower()
        if not in_ing and re.match(r"^\s*ingredients\s*:?\s*$", low):
            in_ing = True
            found_section = True
            continue
        if in_ing:
            if not line or any(b in low for b in SECTION_BREAKERS) or re.match(r"^\s*[A-Za-z ]{3,}\s*:?\s*$", low):
                # End on blank or another section header
                if ingredients_block:
                    break
                else:
