conversation_output.content:
Genetic algorithms (GAs) are population-based metaheuristics inspired by natural selection. They’re effective for problems where the search space is large, non-convex, or riddled with discrete constraints that make classical optimization difficult.

Where GAs fit in real-world finance and budgeting:
- Portfolio allocation: Maximize return for a given risk or vice versa under constraints (bounds, sector caps, turnover, cardinality, transaction costs).
- Capital budgeting: Select projects subject to budget, dependencies, and risk-adjusted value criteria.
- Resource allocation: Assign budgets across departments/products to maximize KPIs with constraints like minimum funding levels or max caps.
- Trading strategy selection: Choose among rules/parameters where search is combinatorial and non-differentiable.
- Scheduling and planning: Optimize staff or resource schedules under complex constraints.

Why GAs help:
- Flexible with non-linear, non-differentiable objectives.
- Handle hard constraints (integer, group, or logical) via repair functions or penalties.
- Provide good-enough solutions quickly when exact methods are infeasible.

Below is a complete example in Go that implements a simple genetic algorithm for a weight budgeting problem (e.g., portfolio weights). The GA allocates weights across N items so that:
- Weights lie within per-asset bounds.
- Weights sum to 1 (full budget).
- Objective = expected return − riskAversion × variance, where variance uses a provided covariance matrix.

You can adapt this to budgeting across departments (replace returns with expected utility per department, and covariance with interdependence/variance estimates).

```python
// You can save this as main.go and run with: go run main.go
package main

import (
	"fmt"
	"log"
	"math"
	"math/rand"
	"time"
)

type Individual struct {
	Weights []float64
	Fitness float64
}

func main() {
	rand.Seed(time.Now().UnixNano())

	// Example data: 5 assets (or budget categories)
	expectedReturns := []float64{0.12, 0.10, 0.07, 0.15, 0.09}
	cov := [][]float64{
		{0.10, 0.02, 0.04, 0.00, 0.01},
		{0.02, 0.08, 0.01, 0.03, 0.00},
		{0.04, 0.01, 0.12, 0.02, 0.02},
		{0.00, 0.03, 0.02, 0.15, 0.01},
		{0.01, 0.00, 0.02, 0.01, 0.09},
	}

	n := len(expectedReturns)
	// Per-asset bounds (e.g., min 0%, max 60%)
	minW := make([]float64, n)
	maxW := make([]float64, n)
	for i := 0; i < n; i++ {
		minW[i] = 0.0
		maxW[i] = 0.6
	}

	// GA hyperparameters
	popSize := 200
	generations := 300
	crossoverRate := 0.9
	mutationRate := 0.1
	mutationSigma := 0.05
	tournamentSize := 3
	elitism := 2

	// Risk aversion (lambda): higher penalizes variance more
	riskAversion := 0.5

	// Ensure feasibility of bounds
	sumMin := 0.0
	sumMax := 0.0
	for i := 0; i < n; i++ {
		sumMin += minW[i]
		sumMax += maxW[i]
	}
	if sumMin > 1.0+1e-9 || sumMax < 1.0-1e-9 {
		log.Fatalf("Infeasible bounds: sum(min)=%f, sum(max)=%f; cannot sum to 1", sumMin, sumMax)
	}

	// Initialize population
	pop := make([]Individual, popSize)
	for i := 0; i < popSize; i++ {
		w := randomFeasibleWeights(n, minW, maxW)
		f := objective(w, expectedReturns, cov, riskAversion)
		pop[i] = Individual{Weights: w, Fitness: f}
	}

	best := bestIndividual(pop)
	fmt.Println("Initial best fitness:", best.Fitness)
	fmt.Println("Initial weights:", pretty(best.Weights))

	for gen := 0; gen < generations; gen++ {
		// Sort population by fitness (descending)
		pop = sortByFitness(pop)

		// Keep elites
		nextPop := make([]Individual, 0, popSize)
		for i := 0; i < elitism && i < len(pop); i++ {
			nextPop = append(nextPop, copyIndividual(pop[i]))
		}

		// Generate rest via selection, crossover, mutation
		for len(nextPop) < popSize {
			parent1 := tournamentSelect(pop, tournamentSize)
			parent2 := tournamentSelect(pop, tournamentSize)

			child1 := copyIndividual(parent1)
			child2 := copyIndividual(parent2)

			if rand.Float64() < crossoverRate {
				child1, child2 = uniformCrossover(parent1, parent2)
			}

			mutate(&child1, mutationRate, mutationSigma, minW, maxW)
			mutate(&child2, mutationRate, mutationSigma, minW, maxW)

			// Repair and re-evaluate
			projectToSimplexWithBounds(child1.Weights, minW, maxW)
			child1.Fitness = objective(child1.Weights, expectedReturns, cov, riskAversion)

			projectToSimplexWithBounds(child2.Weights, minW, maxW)
			child2.Fitness = objective(child2.Weights, expectedReturns, cov, riskAversion)

			nextPop = append(nextPop, child1)
			if len(nextPop) < popSize {
				nextPop = append(nextPop, child2)
			}
		}

		pop = nextPop
		currentBest := bestIndividual(pop)

		// Simple logging
		if (gen+1)%25 == 0 || gen == generations-1 {
			fmt.Printf("Gen %d | Best fitness: %.6f | Weights: %s\n",
				gen+1, currentBest.Fitness, pretty(currentBest.Weights))
		}
	}

	// Final result
	pop = sortByFitness(pop)
	best = pop[0]
	fmt.Println("\nFinal best fitness:", best.Fitness)
	fmt.Println("Final weights:", pretty(best.Weights))
	fmt.Printf("Expected return: %.6f, Variance: %.6f\n",
		dot(best.Weights, expectedReturns),
		quadForm(best.Weights, cov))
}

// Objective: maximize return - lambda * variance
func objective(w []float64, expected []float64, cov [][]float64, lambda float64) float64 {
	ret := dot(w, expected)
	variance := quadForm(w, cov)
	return ret - lambda*variance
}

// Create a random feasible weight vector summing to 1 within bounds.
